package com.idtrust.did.provider;

import java.util.UUID;

/**
 * @param tenantId owning tenant, passed through to {@code com.idtrust.kms.key.KeyService#generate}
 *                 for the signing key generated during creation.
 * @param didId    identifier pre-generated by {@code DidService} before the DID string itself is
 *                 known, so that the signing key generated during creation can be linked to it
 *                 (see {@code com.idtrust.kms.key.KeyService#linkToDid}).
 * @param domain   required for {@link DidMethod#WEB}; ignored by {@link DidMethod#KEY}, whose
 *                 identifier is derived purely from generated key material.
 * @param path     optional additional did:web path segments (e.g. {@code "issuers/acme"}).
 */
public record DidCreationRequest(UUID tenantId, UUID didId, String domain, String path) {
}
